-- Expected results were captured from the original T-SQL on SQL Server and are reviewed at step 5.
-- Row order is not asserted here (multiset comparison); step 3 checks order where the source guarantees one.
-- Prerequisites: the spec's tables created and the final conversion deployed.
-- Each case is one transaction and always rolls back.

-- @case 1: LEFT JOINs keep every customer: missing category, contact, method or city give NULL; same person as both contacts; geography as WKT; '' and NULL kept apart
BEGIN;
DELETE FROM sales.customers;
DELETE FROM sales.customer_categories;
DELETE FROM sales.buying_groups;
DELETE FROM application.people;
DELETE FROM application.delivery_methods;
DELETE FROM application.cities;
INSERT INTO sales.customers ("CustomerID", "CustomerName", "CustomerCategoryID", "PrimaryContactPersonID", "AlternateContactPersonID", "BuyingGroupID", "DeliveryMethodID", "DeliveryCityID", "PhoneNumber", "FaxNumber", "WebsiteURL", "DeliveryLocation", "DeliveryRun", "RunPosition") VALUES
  ('1', 'Customer 1', '1', '1', '2', NULL, '1', '1', '(206) 555-0100', '(206) 555-0101', 'http://c1.example.com', 'POINT(-122.25 47.5)', '', NULL),
  ('2', 'Customer 2', '99', '99', NULL, NULL, '99', '99', '(206) 555-0100', '(206) 555-0101', 'http://c2.example.com', NULL, NULL, NULL),
  ('3', 'Customer 3 ', '1', '1', '1', '1', '1', '1', '(206) 555-0100', '(206) 555-0101', 'http://c3.example.com', 'POINT(0.5 -1.75)', NULL, '7');
INSERT INTO sales.customer_categories ("CustomerCategoryID", "CustomerCategoryName") VALUES
  ('1', 'Novelty Shop');
INSERT INTO sales.buying_groups ("BuyingGroupID", "BuyingGroupName") VALUES
  ('1', 'Tailspin Toys');
INSERT INTO application.people ("PersonID", "FullName") VALUES
  ('1', 'Ann Lee'),
  ('2', 'Bo Ng');
INSERT INTO application.delivery_methods ("DeliveryMethodID", "DeliveryMethodName") VALUES
  ('1', 'Delivery Van');
INSERT INTO application.cities ("CityID", "CityName") VALUES
  ('1', 'Seattle');
CREATE TEMP TABLE pp_actual ON COMMIT DROP AS
SELECT "CustomerID", "CustomerName", "CustomerCategoryName", "PrimaryContact", "AlternateContact", "PhoneNumber", "FaxNumber", "BuyingGroupName", "WebsiteURL", "DeliveryMethod", "CityName", ST_AsText("DeliveryLocation") AS "DeliveryLocation", "DeliveryRun", "RunPosition" FROM website.customers;
DO $pp$
DECLARE got text[];
BEGIN
  SELECT array_agg(attname::text ORDER BY attnum) INTO got FROM pg_attribute WHERE attrelid = 'pp_actual'::regclass AND attnum > 0 AND NOT attisdropped;
  IF got IS DISTINCT FROM ARRAY['CustomerID', 'CustomerName', 'CustomerCategoryName', 'PrimaryContact', 'AlternateContact', 'PhoneNumber', 'FaxNumber', 'BuyingGroupName', 'WebsiteURL', 'DeliveryMethod', 'CityName', 'DeliveryLocation', 'DeliveryRun', 'RunPosition']::text[] THEN
    RAISE EXCEPTION 'agreed test failed (%): columns are %, expected %', 'test 01 LEFT JOINs keep every customer: missing category, contact, method or city give NULL; same person as b…', got, ARRAY['CustomerID', 'CustomerName', 'CustomerCategoryName', 'PrimaryContact', 'AlternateContact', 'PhoneNumber', 'FaxNumber', 'BuyingGroupName', 'WebsiteURL', 'DeliveryMethod', 'CityName', 'DeliveryLocation', 'DeliveryRun', 'RunPosition']::text[];
  END IF;
END $pp$;
CREATE TEMP TABLE pp_expected (LIKE pp_actual) ON COMMIT DROP;
INSERT INTO pp_expected VALUES
  ('1', 'Customer 1', 'Novelty Shop', 'Ann Lee', 'Bo Ng', '(206) 555-0100', '(206) 555-0101', NULL, 'http://c1.example.com', 'Delivery Van', 'Seattle', 'POINT(-122.25 47.5)', '', NULL),
  ('2', 'Customer 2', NULL, NULL, NULL, '(206) 555-0100', '(206) 555-0101', NULL, 'http://c2.example.com', NULL, NULL, NULL, NULL, NULL),
  ('3', 'Customer 3 ', 'Novelty Shop', 'Ann Lee', 'Ann Lee', '(206) 555-0100', '(206) 555-0101', 'Tailspin Toys', 'http://c3.example.com', 'Delivery Van', 'Seattle', 'POINT(0.5 -1.75)', NULL, '7');
DO $pp$
DECLARE missing bigint; extra bigint;
BEGIN
  SELECT count(*) INTO missing FROM ((SELECT * FROM pp_expected) EXCEPT ALL (SELECT * FROM pp_actual)) AS d;
  SELECT count(*) INTO extra FROM ((SELECT * FROM pp_actual) EXCEPT ALL (SELECT * FROM pp_expected)) AS d;
  IF missing > 0 OR extra > 0 THEN
    RAISE EXCEPTION 'agreed test failed (%): % expected row(s) missing, % unexpected row(s) in the result', 'test 01 LEFT JOINs keep every customer: missing category, contact, method or city give NULL; same person as b…', missing, extra;
  END IF;
END $pp$;
ROLLBACK;
